args.script:
using UnityEditor;
using UnityEngine;
using System.Collections.Generic;

string fbxPath = "Assets/Animations/Animations/HoldGun/hold_gun_walk.fbx";
string outputPath = "Assets/Animations/Animations/HoldGun/hold_gun_walk_loop.anim";

// Load source clip
var objects = AssetDatabase.LoadAllAssetsAtPath(fbxPath);
AnimationClip sourceClip = null;
foreach (var obj in objects)
{
    if (obj is AnimationClip clip && clip.name == "hold_gun_walk")
    { sourceClip = clip; break; }
}
if (sourceClip == null) { Debug.LogError("Source clip not found!"); return; }

float clipLength = sourceClip.length;
var bindings = AnimationUtility.GetCurveBindings(sourceClip);
Debug.Log($"Source: {sourceClip.name}, length={clipLength}s, bindings={bindings.Length}");

// --- Identify quaternion groups (prefixes with .x/.y/.z/.w) ---
var quatPrefixes = new HashSet<string>();
var allProps = new Dictionary<string, List<string>>(); // prefix -> list of suffixes
foreach (var b in bindings)
{
    string prop = b.propertyName;
    if (prop.EndsWith(".x") || prop.EndsWith(".y") || prop.EndsWith(".z") || prop.EndsWith(".w"))
    {
        string prefix = prop.Substring(0, prop.Length - 2);
        if (!allProps.ContainsKey(prefix)) allProps[prefix] = new List<string>();
        allProps[prefix].Add(prop[prop.Length-1].ToString());
    }
}
foreach (var kvp in allProps)
{
    if (kvp.Value.Count == 4 && kvp.Value.Contains("x") && kvp.Value.Contains("y") && kvp.Value.Contains("z") && kvp.Value.Contains("w"))
        quatPrefixes.Add(kvp.Key);
}
Debug.Log($"Quaternion groups found: {quatPrefixes.Count} ({string.Join(", ", new List<string>(quatPrefixes).ToArray())})");

// --- Create new clip ---
var newClip = new AnimationClip();
newClip.name = "hold_gun_walk_loop";
newClip.legacy = sourceClip.legacy;
newClip.frameRate = sourceClip.frameRate;
newClip.wrapMode = WrapMode.Loop;

// Copy clip settings
var settings = AnimationUtility.GetAnimationClipSettings(sourceClip);
settings.loopTime = true;
AnimationUtility.SetAnimationClipSettings(newClip, settings);

int curvesFixed = 0;

// --- Process quaternion groups ---
foreach (string prefix in quatPrefixes)
{
    EditorCurveBinding bx = default, by = default, bz = default, bw = default;
    foreach (var b in bindings)
    {
        if (b.propertyName == prefix + ".x") bx = b;
        else if (b.propertyName == prefix + ".y") by = b;
        else if (b.propertyName == prefix + ".z") bz = b;
        else if (b.propertyName == prefix + ".w") bw = b;
    }

    var cx = AnimationUtility.GetEditorCurve(sourceClip, bx);
    var cy = AnimationUtility.GetEditorCurve(sourceClip, by);
    var cz = AnimationUtility.GetEditorCurve(sourceClip, bz);
    var cw = AnimationUtility.GetEditorCurve(sourceClip, bw);
    if (cx == null || cy == null || cz == null || cw == null) continue;

    var kx = cx.keys, ky = cy.keys, kz = cz.keys, kw = cw.keys;

    Quaternion firstQ = new Quaternion(kx[0].value, ky[0].value, kz[0].value, kw[0].value).normalized;
    Quaternion lastQ = new Quaternion(kx[kx.Length-1].value, ky[ky.Length-1].value, kz[kz.Length-1].value, kw[kw.Length-1].value).normalized;

    // Ensure same hemisphere
    if (Quaternion.Dot(firstQ, lastQ) < 0) lastQ = new Quaternion(-lastQ.x, -lastQ.y, -lastQ.z, -lastQ.w);

    float angle = Quaternion.Angle(firstQ, lastQ);
    if (angle < 0.5f)
    {
        AnimationUtility.SetEditorCurve(newClip, bx, cx);
        AnimationUtility.SetEditorCurve(newClip, by, cy);
        AnimationUtility.SetEditorCurve(newClip, bz, cz);
        AnimationUtility.SetEditorCurve(newClip, bw, cw);
        continue;
    }

    // deltaQ = lastQ * inverse(firstQ)
    Quaternion deltaQ = lastQ * Quaternion.Inverse(firstQ);
    float totalTime = kx[kx.Length-1].time - kx[0].time;

    var newKx = new Keyframe[kx.Length];
    var newKy = new Keyframe[ky.Length];
    var newKz = new Keyframe[kz.Length];
    var newKw = new Keyframe[kw.Length];

    for (int i = 0; i < kx.Length; i++)
    {
        float t = totalTime > 0 ? (kx[i].time - kx[0].time) / totalTime : 0;
        Quaternion correction = Quaternion.Inverse(Quaternion.Slerp(Quaternion.identity, deltaQ, t));
        Quaternion orig = new Quaternion(kx[i].value, ky[i].value, kz[i].value, kw[i].value).normalized;
        Quaternion adj = (correction * orig).normalized;

        newKx[i] = kx[i]; newKx[i].value = adj.x;
        newKy[i] = ky[i]; newKy[i].value = adj.y;
        newKz[i] = kz[i]; newKz[i].value = adj.z;
        newKw[i] = kw[i]; newKw[i].value = adj.w;
    }

    AnimationUtility.SetEditorCurve(newClip, bx, new AnimationCurve(newKx));
    AnimationUtility.SetEditorCurve(newClip, by, new AnimationCurve(newKy));
    AnimationUtility.SetEditorCurve(newClip, bz, new AnimationCurve(newKz));
    AnimationUtility.SetEditorCurve(newClip, bw, new AnimationCurve(newKw));
    curvesFixed += 4;
    Debug.Log($"  Fixed quat '{prefix}': angle={angle:F3}°");
}

// --- Process scalar curves (non-quaternion) ---
foreach (var b in bindings)
{
    string prop = b.propertyName;
    // Skip quaternion components (already handled)
    bool isQuat = false;
    foreach (string prefix in quatPrefixes)
    {
        if (prop == prefix + ".x" || prop == prefix + ".y" || prop == prefix + ".z" || prop == prefix + ".w")
        { isQuat = true; break; }
    }
    if (isQuat) continue;

    var curve = AnimationUtility.GetEditorCurve(sourceClip, b);
    if (curve == null || curve.keys.Length < 2)
    {
        if (curve != null) AnimationUtility.SetEditorCurve(newClip, b, curve);
        continue;
    }

    var keys = curve.keys;
    float delta = keys[keys.Length-1].value - keys[0].value;

    if (Mathf.Abs(delta) < 0.0001f)
    {
        AnimationUtility.SetEditorCurve(newClip, b, curve);
        continue;
    }

    // Subtract linear ramp
    float totalTime = keys[keys.Length-1].time - keys[0].time;
    var newKeys = new Keyframe[keys.Length];
    for (int i = 0; i < keys.Length; i++)
    {
        float t = totalTime > 0 ? (keys[i].time - keys[0].time) / totalTime : 0;
        newKeys[i] = keys[i];
        newKeys[i].value = keys[i].value - delta * t;
    }
