    }
}
foreach (var kvp in allProps)
{
    if (kvp.Value.Count == 4 && kvp.Value.Contains("x") && kvp.Value.Contains("y") && kvp.Value.Contains("z") && kvp.Value.Contains("w"))
        quatPrefixes.Add(kvp.Key);
}
Debug.Log($"Quaternion groups found: {quatPrefixes.Count} ({string.Join(", ", new List<string>(quatPrefixes).ToArray())})");

