        newKeys[i] = keys[i];
        newKeys[i].value = keys[i].value - delta * t;
    }
    AnimationUtility.SetEditorCurve(newClip, b, new AnimationCurve(newKeys));
    curvesFixed++;

    // Log root curves for diagnostics
    if (b.propertyName.StartsWith("RootT") || b.propertyName.StartsWith("RootQ"))
        Debug.Log($"  Fixed {b.propertyName}: {firstVal:F6} -> {lastVal:F6} (delta={delta:F6})");
