    var keys = curve.keys;
    float firstVal = keys[0].value;
    float lastVal = keys[keys.Length - 1].value;
    float delta = lastVal - firstVal;

    // KEEP RootT.z — this is forward root motion
    if (b.propertyName == "RootT.z")
    {
