    "Left Forearm Stretch", "Left Forearm Twist In-Out",
    "Left Hand Down-Up", "Left Hand In-Out",
    "Right Shoulder Down-Up", "Right Shoulder Front-Back",
    "Right Arm Down-Up", "Right Arm Front-Back", "Right Arm Twist In-Out",
    "Right Forearm Stretch", "Right Forearm Twist In-Out",
    "Right Hand Down-Up", "Right Hand In-Out",
    "LeftHandT.x", "LeftHandT.y", "LeftHandT.z",
    "LeftHandQ.x", "LeftHandQ.y", "LeftHandQ.z", "LeftHandQ.w",
    "RightHandT.x", "RightHandT.y", "RightHandT.z",
    "RightHandQ.x", "RightHandQ.y", "RightHandQ.z", "RightHandQ.w",
    "Left Eye Down-Up", "Left Eye In-Out", "Right Eye Down-Up", "Right Eye In-Out",
    "Left Toes Up-Down", "Right Toes Up-Down"
};

// Finger props (all LeftHand.* and RightHand.* )
foreach (var b in idleBindings)
{
    if (b.propertyName.StartsWith("LeftHand.") || b.propertyName.StartsWith("RightHand."))
        upperBodyProps = AddToArray(upperBodyProps, b.propertyName);
}
string[] AddToArray(string[] arr, string val) { var l = new List<string>(arr) { val }; return l.ToArray(); }

// ============================================================
// CROUCH PARAMETERS
// ============================================================
float standY = GetFirst(idleCurves, "RootT.y", 0.92f);
float crouchY = standY * 0.62f; // ~0.57

// Crouch leg values (more bent than standing)
float crouchLeftUpperLegFB = 0.45f;
float crouchRightUpperLegFB = 0.45f;
float crouchLeftLowerLegStretch = -0.15f;
float crouchRightLowerLegStretch = -0.15f;
float crouchLeftUpperLegIO = 0.15f;
float crouchRightUpperLegIO = 0.15f;
float crouchLeftFootUD = -0.35f;
float crouchRightFootUD = -0.35f;

// Slight forward lean for crouch
float crouchSpineFB = GetFirst(idleCurves, "Spine Front-Back", -0.075f) - 0.05f;
float crouchChestFB = GetFirst(idleCurves, "Chest Front-Back", -0.15f) - 0.05f;
float crouchUpperChestFB = GetFirst(idleCurves, "UpperChest Front-Back", -0.30f) - 0.03f;

