float idleRootQy = GetFirst(idleCurves, "RootQ.y", 0.373f);
float idleRootQz = GetFirst(idleCurves, "RootQ.z", -0.034f);
float idleRootQw = GetFirst(idleCurves, "RootQ.w", 0.92f);

