var crouchIdleData = new Dictionary<string, List<Keyframe>>();

// Upper body: from idle, with breathing added to spine/chest/upperchest
foreach (string prop in upperBodyProps)
{
    if (!idleCurves.ContainsKey(prop)) continue;
