    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= breathSteps; i++)
        {
            float t = (float)i / breathSteps * breathDuration;
            float breath = 0.008f * Mathf.Sin(2f * Mathf.PI * breathFreq * t / breathDuration);
            keys.Add(new Keyframe(t, crouchSpineFB + breath));
        }
        crouchIdleData[prop] = keys;
    }
    else if (prop == "Chest Front-Back")
    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= breathSteps; i++)
        {
            float t = (float)i / breathSteps * breathDuration;
            float breath = 0.012f * Mathf.Sin(2f * Mathf.PI * breathFreq * t / breathDuration);
            keys.Add(new Keyframe(t, crouchChestFB + breath));
        }
        crouchIdleData[prop] = keys;
    }
    else if (prop == "UpperChest Front-Back")
    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= breathSteps; i++)
        {
            float t = (float)i / breathSteps * breathDuration;
            float breath = 0.015f * Mathf.Sin(2f * Mathf.PI * breathFreq * t / breathDuration);
            keys.Add(new Keyframe(t, crouchUpperChestFB + breath));
        }
        crouchIdleData[prop] = keys;
    }
    else
    {
        SetConstant(crouchIdleData, prop, baseVal);
    }
}

// Root: crouch height with subtle breathing bob
{
    var keysY = new List<Keyframe>();
    var keysX = new List<Keyframe>();
    var keysZ = new List<Keyframe>();
    for (int i = 0; i <= breathSteps; i++)
    {
        float t = (float)i / breathSteps * breathDuration;
        float breath = 0.005f * Mathf.Sin(2f * Mathf.PI * breathFreq * t / breathDuration);
        keysY.Add(new Keyframe(t, crouchY + breath));
        keysX.Add(new Keyframe(t, GetFirst(idleCurves, "RootT.x", 0.038f)));
        keysZ.Add(new Keyframe(t, GetFirst(idleCurves, "RootT.z", 0.057f)));
    }
    crouchIdleData["RootT.x"] = keysX;
    crouchIdleData["RootT.y"] = keysY;
    crouchIdleData["RootT.z"] = keysZ;
}

// Root rotation: constant (slight forward lean for crouch)
SetConstant(crouchIdleData, "RootQ.x", idleRootQx + 0.03f);
SetConstant(crouchIdleData, "RootQ.y", idleRootQy);
SetConstant(crouchIdleData, "RootQ.z", idleRootQz);
SetConstant(crouchIdleData, "RootQ.w", idleRootQw);

// Legs: crouch position (constant, slight asymmetry for natural look)
SetConstant(crouchIdleData, "Left Upper Leg Front-Back", crouchLeftUpperLegFB);
SetConstant(crouchIdleData, "Right Upper Leg Front-Back", crouchRightUpperLegFB);
SetConstant(crouchIdleData, "Left Upper Leg In-Out", crouchLeftUpperLegIO);
SetConstant(crouchIdleData, "Right Upper Leg In-Out", crouchRightUpperLegIO);
SetConstant(crouchIdleData, "Left Upper Leg Twist In-Out", GetFirst(idleCurves, "Left Upper Leg Twist In-Out", 0.26f));
SetConstant(crouchIdleData, "Right Upper Leg Twist In-Out", GetFirst(idleCurves, "Right Upper Leg Twist In-Out", 0.20f));
SetConstant(crouchIdleData, "Left Lower Leg Stretch", crouchLeftLowerLegStretch);
SetConstant(crouchIdleData, "Right Lower Leg Stretch", crouchRightLowerLegStretch);
SetConstant(crouchIdleData, "Left Lower Leg Twist In-Out", GetFirst(idleCurves, "Left Lower Leg Twist In-Out", -0.15f));
SetConstant(crouchIdleData, "Right Lower Leg Twist In-Out", GetFirst(idleCurves, "Right Lower Leg Twist In-Out", -0.06f));
SetConstant(crouchIdleData, "Left Foot Up-Down", crouchLeftFootUD);
SetConstant(crouchIdleData, "Right Foot Up-Down", crouchRightFootUD);
SetConstant(crouchIdleData, "Left Foot Twist In-Out", GetFirst(idleCurves, "Left Foot Twist In-Out", -0.16f));
SetConstant(crouchIdleData, "Right Foot Twist In-Out", GetFirst(idleCurves, "Right Foot Twist In-Out", -0.49f));

// Foot IK targets (adjusted for crouch)
SetConstant(crouchIdleData, "LeftFootT.x", GetFirst(idleCurves, "LeftFootT.x", -0.22f));
SetConstant(crouchIdleData, "LeftFootT.y", GetFirst(idleCurves, "LeftFootT.y", -0.90f) + (crouchY - standY) * 0.5f);
SetConstant(crouchIdleData, "LeftFootT.z", GetFirst(idleCurves, "LeftFootT.z", 0.17f));
SetConstant(crouchIdleData, "RightFootT.x", GetFirst(idleCurves, "RightFootT.x", 0.25f));
SetConstant(crouchIdleData, "RightFootT.y", GetFirst(idleCurves, "RightFootT.y", -0.95f) + (crouchY - standY) * 0.5f);
SetConstant(crouchIdleData, "RightFootT.z", GetFirst(idleCurves, "RightFootT.z", 0.04f));

// Foot rotations (keep from idle)
SetConstant(crouchIdleData, "LeftFootQ.x", GetFirst(idleCurves, "LeftFootQ.x"));
SetConstant(crouchIdleData, "LeftFootQ.y", GetFirst(idleCurves, "LeftFootQ.y"));
SetConstant(crouchIdleData, "LeftFootQ.z", GetFirst(idleCurves, "LeftFootQ.z"));
SetConstant(crouchIdleData, "LeftFootQ.w", GetFirst(idleCurves, "LeftFootQ.w"));
SetConstant(crouchIdleData, "RightFootQ.x", GetFirst(idleCurves, "RightFootQ.x"));
SetConstant(crouchIdleData, "RightFootQ.y", GetFirst(idleCurves, "RightFootQ.y"));
SetConstant(crouchIdleData, "RightFootQ.z", GetFirst(idleCurves, "RightFootQ.z"));
SetConstant(crouchIdleData, "RightFootQ.w", GetFirst(idleCurves, "RightFootQ.w"));

