crouchIdleClip.name = "hold_gun_crouch_idle";
crouchIdleClip.frameRate = 60;
crouchIdleClip.wrapMode = WrapMode.Loop;
var idleSettings = AnimationUtility.GetAnimationClipSettings(idleClip);
idleSettings.loopTime = true;
AnimationUtility.SetAnimationClipSettings(crouchIdleClip, idleSettings);

foreach (var kvp in crouchIdleData)
{
    var binding = new EditorCurveBinding { path = "", propertyName = kvp.Key };
    if (kvp.Key.StartsWith("Root") || kvp.Key.StartsWith("Left") || kvp.Key.StartsWith("Right") || 
        kvp.Key.Contains("Eye") || kvp.Key.Contains("Hand") || kvp.Key.Contains("Spine") ||
        kvp.Key.Contains("Chest") || kvp.Key.Contains("Neck") || kvp.Key.Contains("Head") ||
        kvp.Key.Contains("Shoulder") || kvp.Key.Contains("Arm") || kvp.Key.Contains("Forearm") ||
        kvp.Key.Contains("Foot") || kvp.Key.Contains("Leg") || kvp.Key.Contains("Toes"))
    {
        binding.type = typeof(Animator);
    }
    AnimationUtility.SetEditorCurve(crouchIdleClip, binding, new AnimationCurve(kvp.Value.ToArray()));
}

string idleOutPath = "Assets/Animations/Animations/HoldGun/hold_gun_crouch_idle.anim";
if (AssetDatabase.LoadAssetAtPath<AnimationClip>(idleOutPath) != null)
    AssetDatabase.DeleteAsset(idleOutPath);
AssetDatabase.CreateAsset(crouchIdleClip, idleOutPath);
Debug.Log($"Created crouch idle: {idleOutPath}");

// ============================================================
// CLIP 2: CROUCH WALK (hold_gun_crouch_walk.anim)
// ============================================================
float walkDuration = walkClip.length; // 2.25s

var crouchWalkData = new Dictionary<string, List<Keyframe>>();

// Upper body: from idle (static gun pose, with crouch lean)
foreach (string prop in upperBodyProps)
{
    if (!idleCurves.ContainsKey(prop)) continue;
    float baseVal = idleCurves[prop].keys[0].value;

    if (prop == "Spine Front-Back")
        SetConstant(crouchWalkData, prop, crouchSpineFB);
    else if (prop == "Chest Front-Back")
        SetConstant(crouchWalkData, prop, crouchChestFB);
    else if (prop == "UpperChest Front-Back")
        SetConstant(crouchWalkData, prop, crouchUpperChestFB);
    else
        SetConstant(crouchWalkData, prop, baseVal);
}

// Root: crouch height, forward motion
float walkRootZStart = GetFirst(walkCurves, "RootT.z", 0.23f);
float walkRootZEnd = GetFirst(walkCurves, "RootT.z", 0.23f);
// Use last key value
if (walkCurves.ContainsKey("RootT.z"))
    walkRootZEnd = walkCurves["RootT.z"].keys[walkCurves["RootT.z"].keys.Length - 1].value;
float walkDeltaZ = walkRootZEnd - walkRootZStart;

// RootT.z: linear forward motion (preserved)
var rootZKeys = new List<Keyframe>();
for (int i = 0; i <= 90; i++)
{
    float t = (float)i / 90 * walkDuration;
    float z = walkRootZStart + walkDeltaZ * (t / walkDuration);
    rootZKeys.Add(new Keyframe(t, z));
}
crouchWalkData["RootT.z"] = rootZKeys;

// RootT.y: crouch height with walking bob
var rootYKeys = new List<Keyframe>();
if (walkCurves.ContainsKey("RootT.y"))
{
    var srcY = walkCurves["RootT.y"];
    float walkYAvg = 0f;
    foreach (var k in srcY.keys) walkYAvg += k.value;
    walkYAvg /= srcY.keys.Length;
    float walkYRange = 0f;
    foreach (var k in srcY.keys) walkYRange = Mathf.Max(walkYRange, Mathf.Abs(k.value - walkYAvg));

    foreach (var k in srcY.keys)
    {
        float normalizedBob = (k.value - walkYAvg) / (walkYRange > 0.001f ? walkYRange : 1f);
        rootYKeys.Add(new Keyframe(k.time, crouchY + normalizedBob * walkYRange * 0.5f));
    }
}
else
{
    rootYKeys.Add(new Keyframe(0f, crouchY));
    rootYKeys.Add(new Keyframe(walkDuration, crouchY));
}
crouchWalkData["RootT.y"] = rootYKeys;

// RootT.x: minimal sway
var rootXKeys = new List<Keyframe>();
if (walkCurves.ContainsKey("RootT.x"))
{
    var srcX = walkCurves["RootT.x"];
    float xStart = srcX.keys[0].value;
    foreach (var k in srcX.keys)
    {
        float delta = k.value - xStart; // remove drift, keep oscillation
        rootXKeys.Add(new Keyframe(k.time, GetFirst(idleCurves, "RootT.x", 0.038f) + delta * 0.5f));
    }
}
else
{
    rootXKeys.Add(new Keyframe(0f, GetFirst(idleCurves, "RootT.x", 0.038f)));
    rootXKeys.Add(new Keyframe(walkDuration, GetFirst(idleCurves, "RootT.x", 0.038f)));
}
crouchWalkData["RootT.x"] = rootXKeys;

// RootQ: keep from walk but make periodic
string[] rootQProps = { "RootQ.x", "RootQ.y", "RootQ.z", "RootQ.w" };
foreach (string prop in rootQProps)
{
    if (!walkCurves.ContainsKey(prop)) { SetConstant(crouchWalkData, prop, GetFirst(idleCurves, prop)); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;
    var keys = new List<Keyframe>();
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        keys.Add(new Keyframe(k.time, k.value - delta * t));
    }
    crouchWalkData[prop] = keys;
}

// Legs: from walk but adjusted for crouch (add crouch offset)
string[] legProps = {
    "Left Upper Leg Front-Back", "Left Upper Leg In-Out", "Left Upper Leg Twist In-Out",
    "Left Lower Leg Stretch", "Left Lower Leg Twist In-Out",
    "Left Foot Up-Down", "Left Foot Twist In-Out",
    "Right Upper Leg Front-Back", "Right Upper Leg In-Out", "Right Upper Leg Twist In-Out",
    "Right Lower Leg Stretch", "Right Lower Leg Twist In-Out",
    "Right Foot Up-Down", "Right Foot Twist In-Out"
};

foreach (string prop in legProps)
{
    if (!walkCurves.ContainsKey(prop)) { SetConstant(crouchWalkData, prop, 0f); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;

    // Crouch offset: shift towards crouched position
    float crouchOffset = 0f;
    if (prop.Contains("Upper Leg Front-Back")) crouchOffset = 0.3f; // more forward
    else if (prop.Contains("Lower Leg Stretch")) crouchOffset = -0.2f; // more bent
    else if (prop.Contains("Foot Up-Down")) crouchOffset = 0.15f; // adjust foot

    var keys = new List<Keyframe>();
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        float val = k.value - delta * t + crouchOffset; // periodic + crouch offset
        keys.Add(new Keyframe(k.time, val));
    }
    crouchWalkData[prop] = keys;
}

// Foot IK: from walk, adjusted for crouch height, periodic
string[] footIKProps = { "LeftFootT.x", "LeftFootT.y", "LeftFootT.z",
    "LeftFootQ.x", "LeftFootQ.y", "LeftFootQ.z", "LeftFootQ.w",
    "RightFootT.x", "RightFootT.y", "RightFootT.z",
    "RightFootQ.x", "RightFootQ.y", "RightFootQ.z", "RightFootQ.w" };

foreach (string prop in footIKProps)
{
    if (!walkCurves.ContainsKey(prop)) { SetConstant(crouchWalkData, prop, GetFirst(idleCurves, prop)); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;
    float crouchAdj = 0f;
    if (prop == "LeftFootT.y" || prop == "RightFootT.y")
        crouchAdj = (crouchY - standY) * 0.5f;

    var keys = new List<Keyframe>();
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        keys.Add(new Keyframe(k.time, k.value - delta * t + crouchAdj));
    }
    crouchWalkData[prop] = keys;
}

// Build crouch walk clip
var crouchWalkClip = new AnimationClip();
crouchWalkClip.name = "hold_gun_crouch_walk";
crouchWalkClip.frameRate = 60;
crouchWalkClip.wrapMode = WrapMode.Loop;
var walkSettings = AnimationUtility.GetAnimationClipSettings(walkClip);
walkSettings.loopTime = true;
AnimationUtility.SetAnimationClipSettings(crouchWalkClip, walkSettings);

foreach (var kvp in crouchWalkData)
{
    var binding = new EditorCurveBinding { path = "", propertyName = kvp.Key };
    binding.type = typeof(Animator);
    AnimationUtility.SetEditorCurve(crouchWalkClip, binding, new AnimationCurve(kvp.Value.ToArray()));
}

string walkOutPath = "Assets/Animations/Animations/HoldGun/hold_gun_crouch_walk.anim";
if (AssetDatabase.LoadAssetAtPath<AnimationClip>(walkOutPath) != null)
    AssetDatabase.DeleteAsset(walkOutPath);
AssetDatabase.CreateAsset(crouchWalkClip, walkOutPath);

AssetDatabase.SaveAssets();

// ============================================================
// VERIFICATION
// ============================================================
Debug.Log("=== VERIFICATION ===");

// Crouch idle: all curves should be periodic
int idleBad = 0;
foreach (var b in AnimationUtility.GetCurveBindings(crouchIdleClip))
{
    var c = AnimationUtility.GetEditorCurve(crouchIdleClip, b);
    if (c == null || c.keys.Length < 2) continue;
    float d = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    if (Mathf.Abs(d) > 0.001f) idleBad++;
}
Debug.Log($"Crouch Idle: {idleBad} curves with delta > 0.001 (should be 0)");

// Crouch walk: all periodic except RootT.z
int walkBad = 0;
foreach (var b in AnimationUtility.GetCurveBindings(crouchWalkClip))
{
    if (b.propertyName == "RootT.z") continue; // expected non-periodic
    var c = AnimationUtility.GetEditorCurve(crouchWalkClip, b);
    if (c == null || c.keys.Length < 2) continue;
    float d = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    if (Mathf.Abs(d) > 0.001f) walkBad++;
}
Debug.Log($"Crouch Walk: {walkBad} non-root curves with delta > 0.001 (should be 0)");

// Root motion check
var walkZCurve = AnimationUtility.GetEditorCurve(crouchWalkClip, 
    AnimationUtility.GetCurveBindings(crouchWalkClip)[0]);
foreach (var b in AnimationUtility.GetCurveBindings(crouchWalkClip))
{
    if (b.propertyName == "RootT.z")
    {
        var c = AnimationUtility.GetEditorCurve(crouchWalkClip, b);
        Debug.Log($"RootT.z: start={c.keys[0].value:F4} end={c.keys[c.keys.Length-1].value:F4} (root motion)");
    }
    if (b.propertyName == "RootT.y")
    {
        var c = AnimationUtility.GetEditorCurve(crouchWalkClip, b);
        float avg = 0; foreach (var k in c.keys) avg += k.value; avg /= c.keys.Length;
        Debug.Log($"RootT.y: avg={avg:F4} (crouch height, standing was {standY:F4})");
    }
}

