using UnityEditor;
using UnityEngine;

var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Animations/Animations/HoldGun/hold_gun_crouch_walk.anim");

// Fix RootT.y and RootT.x: subtract linear ramp to make periodic
foreach (var b in AnimationUtility.GetCurveBindings(clip))
{
    if (b.propertyName != "RootT.y" && b.propertyName != "RootT.x") continue;
    var c = AnimationUtility.GetEditorCurve(clip, b);
    if (c == null || c.keys.Length < 2) continue;

    float delta = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    float totalT = c.keys[c.keys.Length - 1].time - c.keys[0].time;

    var newKeys = new Keyframe[c.keys.Length];
    for (int i = 0; i < c.keys.Length; i++)
    {
        float t = totalT > 0 ? (c.keys[i].time - c.keys[0].time) / totalT : 0;
        newKeys[i] = c.keys[i];
        newKeys[i].value = c.keys[i].value - delta * t;
    }
    AnimationUtility.SetEditorCurve(clip, b, new AnimationCurve(newKeys));
    Debug.Log($"Fixed {b.propertyName}: delta {delta:F6} -> 0");
}

// Re-verify
int bad = 0;
foreach (var b in AnimationUtility.GetCurveBindings(clip))
{
    if (b.propertyName == "RootT.z") continue;
    var c = AnimationUtility.GetEditorCurve(clip, b);
    if (c == null || c.keys.Length < 2) continue;
    float d = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    if (Mathf.Abs(d) > 0.001f) bad++;
}
Debug.Log($"Verification: {bad} non-root curves with delta > 0.001 (should be 0)");

// Check root motion preserved
foreach (var b in AnimationUtility.GetCurveBindings(clip))
{
    if (b.propertyName == "RootT.z")
    {
        var c = AnimationUtility.GetEditorCurve(clip, b);
        Debug.Log($"RootT.z: {c.keys[0].value:F4} -> {c.keys[c.keys.Length-1].value:F4} (root motion preserved)");
    }
}

EditorUtility.SetDirty(clip);
AssetDatabase.SaveAssets();

