args.script:
using UnityEditor;
using UnityEngine;
using System.Collections.Generic;

string idlePath = "Assets/Animations/Animations/HoldGun/hold_gun_idle.fbx";
string walkPath = "Assets/Animations/Animations/HoldGun/hold_gun_walk.fbx";

AnimationClip idleClip = null;
AnimationClip walkClip = null;
foreach (var obj in AssetDatabase.LoadAllAssetsAtPath(idlePath))
    if (obj is AnimationClip c && c.name == "hold_gun_idle") { idleClip = c; break; }
foreach (var obj in AssetDatabase.LoadAllAssetsAtPath(walkPath))
    if (obj is AnimationClip c && c.name == "hold_gun_walk") { walkClip = c; break; }
if (idleClip == null || walkClip == null) { Debug.LogError("Source clips not found!"); return; }

Dictionary<string, AnimationCurve> GetCurves(AnimationClip clip)
{
    var dict = new Dictionary<string, AnimationCurve>();
    foreach (var b in AnimationUtility.GetCurveBindings(clip))
    {
        var c = AnimationUtility.GetEditorCurve(clip, b);
        if (c != null) dict[b.propertyName] = c;
    }
    return dict;
}
var idleCurves = GetCurves(idleClip);
var walkCurves = GetCurves(walkClip);

float GetFirst(Dictionary<string, AnimationCurve> dict, string key, float fb = 0f)
{
    if (dict.ContainsKey(key) && dict[key].keys.Length > 0) return dict[key].keys[0].value;
    return fb;
}

void SetConst(Dictionary<string, List<Keyframe>> clip, string prop, float val)
{
    clip[prop] = new List<Keyframe> { new Keyframe(0f, val), new Keyframe(0.01f, val) };
}

// ============= UPPER BODY PROPS (from idle) =============
var upperBodyProps = new List<string> {
    "Spine Front-Back", "Spine Left-Right", "Spine Twist Left-Right",
    "Chest Front-Back", "Chest Left-Right", "Chest Twist Left-Right",
    "UpperChest Front-Back", "UpperChest Left-Right", "UpperChest Twist Left-Right",
    "Neck Nod Down-Up", "Neck Tilt Left-Right", "Neck Turn Left-Right",
    "Head Nod Down-Up", "Head Tilt Left-Right", "Head Turn Left-Right",
    "Left Shoulder Down-Up", "Left Shoulder Front-Back",
    "Left Arm Down-Up", "Left Arm Front-Back", "Left Arm Twist In-Out",
    "Left Forearm Stretch", "Left Forearm Twist In-Out",
    "Left Hand Down-Up", "Left Hand In-Out",
    "Right Shoulder Down-Up", "Right Shoulder Front-Back",
    "Right Arm Down-Up", "Right Arm Front-Back", "Right Arm Twist In-Out",
    "Right Forearm Stretch", "Right Forearm Twist In-Out",
    "Right Hand Down-Up", "Right Hand In-Out",
    "LeftHandT.x", "LeftHandT.y", "LeftHandT.z",
    "LeftHandQ.x", "LeftHandQ.y", "LeftHandQ.z", "LeftHandQ.w",
    "RightHandT.x", "RightHandT.y", "RightHandT.z",
    "RightHandQ.x", "RightHandQ.y", "RightHandQ.z", "RightHandQ.w",
    "Left Eye Down-Up", "Left Eye In-Out", "Right Eye Down-Up", "Right Eye In-Out",
    "Left Toes Up-Down", "Right Toes Up-Down"
};
foreach (var b in idleBindings_list(idleClip))
    if (b.propertyName.StartsWith("LeftHand.") || b.propertyName.StartsWith("RightHand."))
        upperBodyProps.Add(b.propertyName);
EditorCurveBinding[] idleBindings_list(AnimationClip c) { return AnimationUtility.GetCurveBindings(c); }

// ============= CROUCH PARAMETERS =============
float standY = GetFirst(idleCurves, "RootT.y", 0.92f);
float crouchY = standY * 0.55f; // ~0.506, deep crouch
float heightDelta = standY - crouchY; // how much hips drop

// Deep crouch leg values
float cULegFB = 0.65f;    // Upper Leg Front-Back: strong forward rotation
float cLLegStretch = -0.45f; // Lower Leg Stretch: deep knee bend
float cULegIO = 0.12f;     // Upper Leg In-Out: slight outward
float cFootUD = -0.15f;    // Foot Up-Down: flatter foot
float cFootTIO = GetFirst(idleCurves, "Left Foot Twist In-Out", -0.16f);

// Forward lean
float crouchSpineFB = GetFirst(idleCurves, "Spine Front-Back", -0.075f) - 0.08f;
float crouchChestFB = GetFirst(idleCurves, "Chest Front-Back", -0.15f) - 0.06f;
float crouchUChestFB = GetFirst(idleCurves, "UpperChest Front-Back", -0.30f) - 0.04f;

// Foot IK Y: feet stay on ground, so relative to root they are CLOSER
// idle: RootT.y=0.92, LeftFootT.y=-0.90 => foot world Y ≈ 0.02
// crouch: RootT.y=0.51, foot world Y ≈ 0.02 => LeftFootT.y = 0.02 - 0.51 = -0.49
float idleFootY_L = GetFirst(idleCurves, "LeftFootT.y", -0.90f);
float idleFootY_R = GetFirst(idleCurves, "RightFootT.y", -0.95f);
// World foot Y from idle: root_y + footT_y
float footWorldY_L = standY + idleFootY_L;
float footWorldY_R = standY + idleFootY_R;
float crouchFootTY_L = footWorldY_L - crouchY; // e.g. 0.02 - 0.51 = -0.49
float crouchFootTY_R = footWorldY_R - crouchY;

Debug.Log($"standY={standY:F3} crouchY={crouchY:F3} heightDelta={heightDelta:F3}");
Debug.Log($"Foot L: idle={idleFootY_L:F3} world={footWorldY_L:F3} crouch_rel={crouchFootTY_L:F3}");
Debug.Log($"Foot R: idle={idleFootY_R:F3} world={footWorldY_R:F3} crouch_rel={crouchFootTY_R:F3}");

// ============================================================
// CLIP 1: CROUCH BREATHING
// ============================================================
float breathDur = 2.0f;
int steps = 60;
var ciData = new Dictionary<string, List<Keyframe>>();

// Upper body with breathing
foreach (string prop in upperBodyProps)
{
    if (!idleCurves.ContainsKey(prop)) continue;
    float baseVal = idleCurves[prop].keys[0].value;

    if (prop == "Spine Front-Back")
    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= steps; i++)
        {
            float t = (float)i / steps * breathDur;
            float breath = 0.01f * Mathf.Sin(Mathf.PI * t / breathDur);
            keys.Add(new Keyframe(t, crouchSpineFB + breath));
        }
        ciData[prop] = keys;
    }
    else if (prop == "Chest Front-Back")
    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= steps; i++)
        {
            float t = (float)i / steps * breathDur;
            float breath = 0.015f * Mathf.Sin(Mathf.PI * t / breathDur);
            keys.Add(new Keyframe(t, crouchChestFB + breath));
        }
        ciData[prop] = keys;
    }
    else if (prop == "UpperChest Front-Back")
    {
        var keys = new List<Keyframe>();
        for (int i = 0; i <= steps; i++)
        {
            float t = (float)i / steps * breathDur;
            float breath = 0.018f * Mathf.Sin(Mathf.PI * t / breathDur);
            keys.Add(new Keyframe(t, crouchUChestFB + breath));
        }
        ciData[prop] = keys;
    }
    else
        SetConst(ciData, prop, baseVal);
}

// Root: crouch height with subtle breathing bob
{
    var keysY = new List<Keyframe>();
    for (int i = 0; i <= steps; i++)
    {
        float t = (float)i / steps * breathDur;
        float breath = 0.006f * Mathf.Sin(Mathf.PI * t / breathDur);
        keysY.Add(new Keyframe(t, crouchY + breath));
    }
    ciData["RootT.y"] = keysY;
    SetConst(ciData, "RootT.x", GetFirst(idleCurves, "RootT.x", 0.038f));
    SetConst(ciData, "RootT.z", GetFirst(idleCurves, "RootT.z", 0.057f));
}

// Root rotation: forward lean
SetConst(ciData, "RootQ.x", GetFirst(idleCurves, "RootQ.x", 0.115f) + 0.05f);
SetConst(ciData, "RootQ.y", GetFirst(idleCurves, "RootQ.y", 0.373f));
SetConst(ciData, "RootQ.z", GetFirst(idleCurves, "RootQ.z", -0.034f));
SetConst(ciData, "RootQ.w", GetFirst(idleCurves, "RootQ.w", 0.92f));

// Legs: deep crouch
SetConst(ciData, "Left Upper Leg Front-Back", cULegFB);
SetConst(ciData, "Right Upper Leg Front-Back", cULegFB);
SetConst(ciData, "Left Upper Leg In-Out", cULegIO);
SetConst(ciData, "Right Upper Leg In-Out", cULegIO);
SetConst(ciData, "Left Upper Leg Twist In-Out", GetFirst(idleCurves, "Left Upper Leg Twist In-Out", 0.26f));
SetConst(ciData, "Right Upper Leg Twist In-Out", GetFirst(idleCurves, "Right Upper Leg Twist In-Out", 0.20f));
SetConst(ciData, "Left Lower Leg Stretch", cLLegStretch);
SetConst(ciData, "Right Lower Leg Stretch", cLLegStretch);
SetConst(ciData, "Left Lower Leg Twist In-Out", GetFirst(idleCurves, "Left Lower Leg Twist In-Out", -0.15f));
SetConst(ciData, "Right Lower Leg Twist In-Out", GetFirst(idleCurves, "Right Lower Leg Twist In-Out", -0.06f));
SetConst(ciData, "Left Foot Up-Down", cFootUD);
SetConst(ciData, "Right Foot Up-Down", cFootUD);
SetConst(ciData, "Left Foot Twist In-Out", GetFirst(idleCurves, "Left Foot Twist In-Out", -0.16f));
SetConst(ciData, "Right Foot Twist In-Out", GetFirst(idleCurves, "Right Foot Twist In-Out", -0.49f));

// Foot IK: feet on ground, adjusted for crouch height
SetConst(ciData, "LeftFootT.x", GetFirst(idleCurves, "LeftFootT.x", -0.22f));
SetConst(ciData, "LeftFootT.y", crouchFootTY_L);
SetConst(ciData, "LeftFootT.z", GetFirst(idleCurves, "LeftFootT.z", 0.17f));
SetConst(ciData, "RightFootT.x", GetFirst(idleCurves, "RightFootT.x", 0.25f));
SetConst(ciData, "RightFootT.y", crouchFootTY_R);
SetConst(ciData, "RightFootT.z", GetFirst(idleCurves, "RightFootT.z", 0.04f));

// Foot rotations from idle
SetConst(ciData, "LeftFootQ.x", GetFirst(idleCurves, "LeftFootQ.x"));
SetConst(ciData, "LeftFootQ.y", GetFirst(idleCurves, "LeftFootQ.y"));
SetConst(ciData, "LeftFootQ.z", GetFirst(idleCurves, "LeftFootQ.z"));
SetConst(ciData, "LeftFootQ.w", GetFirst(idleCurves, "LeftFootQ.w"));
SetConst(ciData, "RightFootQ.x", GetFirst(idleCurves, "RightFootQ.x"));
SetConst(ciData, "RightFootQ.y", GetFirst(idleCurves, "RightFootQ.y"));
SetConst(ciData, "RightFootQ.z", GetFirst(idleCurves, "RightFootQ.z"));
SetConst(ciData, "RightFootQ.w", GetFirst(idleCurves, "RightFootQ.w"));

// Build crouch idle clip
var ciClip = new AnimationClip();
ciClip.name = "hold_gun_crouch_idle";
ciClip.frameRate = 60;
ciClip.wrapMode = WrapMode.Loop;
var ciSettings = AnimationUtility.GetAnimationClipSettings(idleClip);
ciSettings.loopTime = true;
AnimationUtility.SetAnimationClipSettings(ciClip, ciSettings);
foreach (var kvp in ciData)
{
    var binding = new EditorCurveBinding { path = "", propertyName = kvp.Key, type = typeof(Animator) };
    AnimationUtility.SetEditorCurve(ciClip, binding, new AnimationCurve(kvp.Value.ToArray()));
}
string ciOut = "Assets/Animations/Animations/HoldGun/hold_gun_crouch_idle.anim";
if (AssetDatabase.LoadAssetAtPath<AnimationClip>(ciOut) != null) AssetDatabase.DeleteAsset(ciOut);
AssetDatabase.CreateAsset(ciClip, ciOut);
Debug.Log($"Created: {ciOut}");

// ============================================================
// CLIP 2: CROUCH WALK
// ============================================================
float walkDur = walkClip.length;
var cwData = new Dictionary<string, List<Keyframe>>();

// Upper body: static crouch gun pose
foreach (string prop in upperBodyProps)
{
    if (!idleCurves.ContainsKey(prop)) continue;
    float baseVal = idleCurves[prop].keys[0].value;
    if (prop == "Spine Front-Back") SetConst(cwData, prop, crouchSpineFB);
    else if (prop == "Chest Front-Back") SetConst(cwData, prop, crouchChestFB);
    else if (prop == "UpperChest Front-Back") SetConst(cwData, prop, crouchUChestFB);
    else SetConst(cwData, prop, baseVal);
}

// RootT.z: linear forward motion (preserved from walk)
float walkZStart = GetFirst(walkCurves, "RootT.z", 0.23f);
float walkZEnd = walkCurves["RootT.z"].keys[walkCurves["RootT.z"].keys.Length - 1].value;
float walkDZ = walkZEnd - walkZStart;
var rootZKeys = new List<Keyframe>();
for (int i = 0; i <= 90; i++)
{
    float t = (float)i / 90 * walkDur;
    rootZKeys.Add(new Keyframe(t, walkZStart + walkDZ * (t / walkDur)));
}
cwData["RootT.z"] = rootZKeys;

// RootT.y: crouch height with walk bob (periodic)
{
    var srcY = walkCurves["RootT.y"];
    float avg = 0f; foreach (var k in srcY.keys) avg += k.value; avg /= srcY.keys.Length;
    float range = 0f; foreach (var k in srcY.keys) range = Mathf.Max(range, Mathf.Abs(k.value - avg));
    var keys = new List<Keyframe>();
    float first = srcY.keys[0].value;
    float last = srcY.keys[srcY.keys.Length - 1].value;
    float delta = last - first;
    float totalT = srcY.keys[srcY.keys.Length - 1].time - srcY.keys[0].time;
    foreach (var k in srcY.keys)
    {
        float t = totalT > 0 ? (k.time - srcY.keys[0].time) / totalT : 0;
        float normBob = range > 0.001f ? (k.value - avg) / range : 0;
        float val = crouchY + normBob * range * 0.4f; // crouch height + reduced bob
        val -= delta * t; // make periodic
        keys.Add(new Keyframe(k.time, val));
    }
    cwData["RootT.y"] = keys;
}

// RootT.x: sway (periodic)
{
    var srcX = walkCurves["RootT.x"];
    float first = srcX.keys[0].value;
    float last = srcX.keys[srcX.keys.Length - 1].value;
    float delta = last - first;
    float totalT = srcX.keys[srcX.keys.Length - 1].time - srcX.keys[0].time;
    float idleX = GetFirst(idleCurves, "RootT.x", 0.038f);
    var keys = new List<Keyframe>();
    foreach (var k in srcX.keys)
    {
        float t = totalT > 0 ? (k.time - srcX.keys[0].time) / totalT : 0;
        float oscillation = k.value - first; // remove drift, keep oscillation
        keys.Add(new Keyframe(k.time, idleX + oscillation * 0.4f));
    }
    cwData["RootT.x"] = keys;
}

// RootQ: periodic from walk
foreach (string prop in new[] { "RootQ.x", "RootQ.y", "RootQ.z", "RootQ.w" })
{
    if (!walkCurves.ContainsKey(prop)) { SetConst(cwData, prop, GetFirst(idleCurves, prop)); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    var keys = new List<Keyframe>();
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        keys.Add(new Keyframe(k.time, k.value - delta * t));
    }
    cwData[prop] = keys;
}

// Legs: from walk + crouch offset, periodic
var legOffset = new Dictionary<string, float> {
    { "Left Upper Leg Front-Back", 0.45f },
    { "Right Upper Leg Front-Back", 0.35f },
    { "Left Upper Leg In-Out", -0.1f },
    { "Right Upper Leg In-Out", -0.15f },
    { "Left Lower Leg Stretch", -0.55f },
    { "Right Lower Leg Stretch", -0.55f },
    { "Left Foot Up-Down", 0.2f },
    { "Right Foot Up-Down", 0.2f },
};
foreach (string prop in new[] {
    "Left Upper Leg Front-Back", "Left Upper Leg In-Out", "Left Upper Leg Twist In-Out",
    "Left Lower Leg Stretch", "Left Lower Leg Twist In-Out",
    "Left Foot Up-Down", "Left Foot Twist In-Out",
    "Right Upper Leg Front-Back", "Right Upper Leg In-Out", "Right Upper Leg Twist In-Out",
    "Right Lower Leg Stretch", "Right Lower Leg Twist In-Out",
    "Right Foot Up-Down", "Right Foot Twist In-Out"
})
{
    if (!walkCurves.ContainsKey(prop)) { SetConst(cwData, prop, 0f); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    float offset = legOffset.ContainsKey(prop) ? legOffset[prop] : 0f;
    var keys = new List<Keyframe>();
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        keys.Add(new Keyframe(k.time, k.value - delta * t + offset));
    }
    cwData[prop] = keys;
}

// Foot IK: from walk, adjusted for crouch height, periodic
foreach (string prop in new[] {
    "LeftFootT.x", "LeftFootT.y", "LeftFootT.z",
    "LeftFootQ.x", "LeftFootQ.y", "LeftFootQ.z", "LeftFootQ.w",
    "RightFootT.x", "RightFootT.y", "RightFootT.z",
    "RightFootQ.x", "RightFootQ.y", "RightFootQ.z", "RightFootQ.w"
})
{
    if (!walkCurves.ContainsKey(prop)) { SetConst(cwData, prop, GetFirst(idleCurves, prop)); continue; }
    var src = walkCurves[prop];
    float first = src.keys[0].value;
    float last = src.keys[src.keys.Length - 1].value;
    float delta = last - first;
    float totalT = src.keys[src.keys.Length - 1].time - src.keys[0].time;
    // Y adjustment: feet stay on ground while root drops
    float yAdj = (prop == "LeftFootT.y" || prop == "RightFootT.y") ? heightDelta : 0f;
    var keys = new List<Keyframe>();
    foreach (var k in src.keys)
    {
        float t = totalT > 0 ? (k.time - src.keys[0].time) / totalT : 0;
        keys.Add(new Keyframe(k.time, k.value - delta * t + yAdj));
    }
    cwData[prop] = keys;
}

// Build crouch walk clip
var cwClip = new AnimationClip();
cwClip.name = "hold_gun_crouch_walk";
cwClip.frameRate = 60;
cwClip.wrapMode = WrapMode.Loop;
var cwSettings = AnimationUtility.GetAnimationClipSettings(walkClip);
cwSettings.loopTime = true;
AnimationUtility.SetAnimationClipSettings(cwClip, cwSettings);
foreach (var kvp in cwData)
{
    var binding = new EditorCurveBinding { path = "", propertyName = kvp.Key, type = typeof(Animator) };
    AnimationUtility.SetEditorCurve(cwClip, binding, new AnimationCurve(kvp.Value.ToArray()));
}
string cwOut = "Assets/Animations/Animations/HoldGun/hold_gun_crouch_walk.anim";
if (AssetDatabase.LoadAssetAtPath<AnimationClip>(cwOut) != null) AssetDatabase.DeleteAsset(cwOut);
AssetDatabase.CreateAsset(cwClip, cwOut);

AssetDatabase.SaveAssets();

// ============================================================
// VERIFICATION
// ============================================================
Debug.Log("=== VERIFICATION ===");

int ciBad = 0;
foreach (var b in AnimationUtility.GetCurveBindings(ciClip))
{
    var c = AnimationUtility.GetEditorCurve(ciClip, b);
    if (c == null || c.keys.Length < 2) continue;
    float d = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    if (Mathf.Abs(d) > 0.001f) ciBad++;
}
Debug.Log($"Crouch Idle: {ciBad} curves with delta > 0.001 (should be 0)");

int cwBad = 0;
foreach (var b in AnimationUtility.GetCurveBindings(cwClip))
{
    if (b.propertyName == "RootT.z") continue;
    var c = AnimationUtility.GetEditorCurve(cwClip, b);
    if (c == null || c.keys.Length < 2) continue;
    float d = c.keys[c.keys.Length - 1].value - c.keys[0].value;
    if (Mathf.Abs(d) > 0.001f) cwBad++;
}
Debug.Log($"Crouch Walk: {cwBad} non-root curves with delta > 0.001 (should be 0)");

// Key values
Debug.Log($"--- Crouch Idle ---");
Debug.Log($"  RootT.y = {crouchY:F3} (standing was {standY:F3}, dropped {heightDelta:F3})");
Debug.Log($"  LeftFootT.y = {crouchFootTY_L:F3} (was {idleFootY_L:F3})");
Debug.Log($"  RightFootT.y = {crouchFootTY_R:F3} (was {idleFootY_R:F3})");
Debug.Log($"  Upper Leg FB = {cULegFB} (idle L={GetFirst(idleCurves, "Left Upper Leg Front-Back"):F3})");
Debug.Log($"  Lower Leg Stretch = {cLLegStretch} (idle L={GetFirst(idleCurves, "Left Lower Leg Stretch"):F3})");

foreach (var b in AnimationUtility.GetCurveBindings(cwClip))
{
    if (b.propertyName == "RootT.z")
    {
        var c = AnimationUtility.GetEditorCurve(cwClip, b);
        Debug.Log($"--- Crouch Walk ---");
        Debug.Log($"  RootT.z: {c.keys[0].value:F4} -> {c.keys[c.keys.Length-1].value:F4} (root motion)");
    }
    if (b.propertyName == "RootT.y")
    {
        var c = AnimationUtility.GetEditorCurve(cwClip, b);
        float avg = 0; foreach (var k in c.keys) avg += k.value; avg /= c.keys.Length;
        Debug.Log($"  RootT.y avg = {avg:F3} (crouch height)");
    }
    if (b.propertyName == "LeftFootT.y")
    {
        var c = AnimationUtility.GetEditorCurve(cwClip, b);
        float avg = 0; foreach (var k in c.keys) avg += k.value; avg /= c.keys.Length;
        Debug.Log($"  LeftFootT.y avg = {avg:F3}");
    }
}

